namespace HakutaiKagami.Core.Contracts;
public static partial class BattlefieldRules
{
 public static BattlefieldCasualties Casualties(ContractWorld w,EntityId unit,long at=long.MaxValue,long rev=long.MaxValue){using var _ccRev=ControlContext.At(rev);var rows=(w.WorldClashes?.Steps??[]).Where(s=>s.At<at||s.At==at&&s.Revision<rev).SelectMany(s=>s.Result.Casualties??[]).Where(c=>c.Unit==unit).ToArray();int recovered=Recovered(w,unit,at,rev);return new(unit,rows.Sum(c=>c.Dead),rows.Sum(c=>c.Wounded)-recovered,rows.Sum(c=>c.Deserted),recovered);}
 public static int Recovered(ContractWorld w,EntityId unit,long at,long rev=long.MaxValue)=>Orders(w).Where(o=>o.Input.Unit==unit&&o.Input.Action==BattlefieldAction.Rest&&Before(o,at,rev)&&o.At+5*86400<=at).Sum(o=>o.Input.Amount);
 public static bool Resting(ContractWorld w,EntityId army,long at)=>Orders(w).Any(o=>o.Army==army&&o.Input.Action==BattlefieldAction.Rest&&o.At<=at&&at<o.At+5*86400);
 internal static long? NextBoundary(ContractWorld w,long target)=>Orders(w).Where(o=>o.Input.Action==BattlefieldAction.Rest&&o.At+5*86400>w.ElapsedSeconds&&o.At+5*86400<=target).Select(o=>(long?)(o.At+5*86400)).Order().FirstOrDefault();
 internal static (long At,long Revision,long Amount)[] RiceTransfers(ContractWorld w,EntityId site,long at,long rev)=>Orders(w).Where(o=>o.Site==site&&o.Input.Action==BattlefieldAction.Rest&&Before(o,at,rev)).Select(o=>(o.At,o.Revision,-3L*o.Input.Amount)).Concat(TempleMilitary.RiceTransfers(w,site,at,rev)).ToArray();
 static EntityId? Home(ContractWorld w,UnitState unit)=>PrivateRecruitment.PrivateUnit(unit.Id)?PrivateRecruitment.VillageOf(w,unit.Id):unit.Id==TempleMilitary.Unit?TempleMilitary.Site:NewGameMilitary.LedgerStates(w).FirstOrDefault(l=>l.Terms.Army==unit.Army)?.Terms.Site??NpcArmies.Musters(w).FirstOrDefault(m=>NewGameMilitary.LedgerIdentity(m.Owner,m.Site).Army==unit.Army)?.Site;
 static BattlefieldCasualties Partition(ContractWorld w,EngagementUnit victim,RegionalLoss loss){int before=(w.WorldClashes?.Steps??[]).Where(s=>s.At<w.ElapsedSeconds).SelectMany(s=>s.Result.Losses).Where(l=>l.Unit==victim.Unit.Id).Sum(l=>l.Soldiers);int wounded=(before+loss.Soldiers)/2-before/2;int remainder=loss.Soldiers-wounded;int deserted=victim.Morale-loss.Morale<=25?remainder:remainder/3;var home=Home(w,victim.Unit);JourneyLeg[] route=[];long? arrival=null;if(deserted>0&&home!=null){var origin=ContinuousWorld.Nearest(victim.Position);string goal=NewGameWorld.Node(home.Value.Value);long first=RegionalGround.Distance(victim.Position,FieldWorld.FromWorld(BranchRoutes.GraphNodes(w).Single(n=>n.Id==origin).Position))/1000;var path=BranchRoutes.Plan(origin,goal,[],w:w,departureAt:w.ElapsedSeconds+first);route=BranchRoutes.Schedule(origin,path,w.ElapsedSeconds+first,w);arrival=route.LastOrDefault()?.EndAt??w.ElapsedSeconds+first;}
 return new(victim.Unit.Id,remainder-deserted,wounded,deserted,0){Home=home,ReturnAt=arrival,ReturnRoute=route};}
 public static int ReturnedDeserters(ContractWorld w,EntityId site,long at,long rev)=>!Enabled(w)?0:(w.WorldClashes?.Steps??[]).Where(s=>s.At<at||s.At==at&&s.Revision<rev).SelectMany(s=>s.Result.Casualties??[]).Where(c=>!PrivateRecruitment.PrivateUnit(c.Unit)&&c.Home==site&&c.ReturnAt<=at).Sum(c=>c.Deserted);
 internal static long ReturnedLaborSeconds(ContractWorld w,EntityId site,long from,long until,long rev)=>!Enabled(w)?0:(w.WorldClashes?.Steps??[]).Where(s=>s.At<until||s.At==until&&s.Revision<rev).SelectMany(s=>s.Result.Casualties??[]).Where(c=>!PrivateRecruitment.PrivateUnit(c.Unit)&&c.Home==site&&c.ReturnAt<until).Sum(c=>checked(c.Deserted*(until-Math.Max(from,c.ReturnAt!.Value))));
 public static int RationStrength(ContractWorld w,long at)=>NewGameMilitary.TotalStrength(w,at)+(Enabled(w)?NewGameMilitary.UnitIdsFor(w).Sum(id=>Casualties(w,id,at).Wounded):0);
}
